JX_CIYU = {
  "ciyu-1": "答案 C。「**原本**」指最初、本来，珍珠最初源于沙子；「**但**」表轻转，说明并非所有沙子都能成珠；「**鹤立鸡群**」呼应前文“卓尔不群”，比喻才能或仪表超出众人；「**承受**」与“忽视和平淡”搭配（受冷落用承受，责任用承担）。全联语义连贯。",
  "ciyu-2": "答案 C。晚风用「**轻柔**」修饰最显温婉；夕阳余晖使湿地像油画，用「**染**」字形象写出色彩慢慢晕染开来；草筏在水面是「**漂浮**」；白鹭盘旋告别用「**依依不舍**」表现留恋深情。",
  "ciyu-3": "答案 C。第一空形容技术达到极致，用「**炉火纯青**」最贴合技艺精湛的修辞语境；第二空工匠精神不仅是技艺，更是精神实质，用「**内涵**」；第三空前有“怎有”，需假设关联词「**如果/倘若**」；第四空“物我两忘”是一种崇高的精神「**境界**」。",
  "ciyu-4": "答案 D。第一空与“重大的”相对，用「**琐碎**」最为精准（繁琐多指手续程序多）；第二空与“平淡无奇”相对，用「**惊心动魄**」形成强烈对比；第三、四空“无论……都……”，后句引出条件假设“「**如果**」……「**就**」会体会到”。",
  "ciyu-5": "答案 B。第一空对大自然顽强微小生命的敬佩，用「**敬畏**」；第二空与“多么”搭配用条件连词「**无论**」；第三空万物自有分量，与前文“微不足道”相对，用「**重若千钧**」；第四空总结每人都有自己的位置与分量，不应轻视自己，用「**妄自菲薄**」。",
  "ciyu-6": "答案 D。四组词与后文动词形成精准反义对举：**开放**总能战胜封闭，**交流**总能战胜隔阂，**融合**总能战胜割裂，**和平**总能战胜对抗；末空并列形容同胞同甘共苦、共同前行，用「**同舟共济/风雨同舟**」，全句逻辑严密。",
  "ciyu-7": "答案 C。第一空表示时代向后延伸递进，用「**以至**」（以至多表程度、数量或范围的延伸）；第二空形容诗人细腻丰富的情感，用「**深沉**」；第三空诗歌展现历史文化并使之永久流传，用「**铭刻**」；第四空诗意中国历史绵长，用「**悠远**」。",
  "ciyu-8": "答案 B。第一空转折写其他人与曹操不同，用「**而**」；第二空形容常人写诗逃避现实、醉态朦胧，用「**朦胧**」；第三空世俗对曹操的常见定势印象是阴险奸诈，用「**阴险**」；末空总结这种性格是长期环境孤立造就的，用「**孤僻**」。",
  "ciyu-9": "答案 D。第一空日子无限持续延展，用「**延续**」；第二空承接上文突感光阴飞逝而产生心理转折，“「**于是**」，你心中升起一种柔情”；第三空比喻时光无情夺走青春美好，用「**劫掠**」更具冲击力；第四空平凡幸福短暂易逝，用「**稍纵即逝**」。",
  "ciyu-10": "答案 B。第一空与浪潮搭配，用「**掀起**」文化浪潮；第二空形容快节奏现代社会的浮躁心态，用「**浮躁**」；第三空唤醒国人温润美好的集体文化记忆，用「**温情**」；第四空形容文化潜移默化、润物无声的教化力量，用「**春风化雨**」。",
  "ciyu-11": "答案 D。第一空和第二空并列关联词，“「**既**」需要……「**又**」需要……”；第三空作文教学按思维发展的内在规律进行，用「**规律**」；第四空思维从具象到抽象再到创造，由浅入深，用「**循序渐进**」（按部就班偏指守规矩，循序渐进侧重知识认知阶梯）。",
  "ciyu-12": "答案 B。第一空形容经典名作流传久远为人称诵，用「**脍炙人口**」；第二空精神文化滋补心灵，用「**滋养**」；第三空记录几千年的时代风云变化，用「**沧桑**」；第四空前后分句构成递进关系，用「**不仅……还……**」。",
  "ciyu-13": "答案 C。（1）“构建人类命运共同体”是固定的时代政论搭配，用「**构建**」；（2）针对青少年的特长潜力，用「**发掘**」（开发常与资源、产品搭配）；（3）前后两个分句形成正反对照，“遵循……方可……；「**反之**」，粗暴对待……必然……”，用反之最为严密。",
  "ciyu-14": "答案 C。三句分别对应人类对祖国不同层面的情感：关心祖国前途命运，愿为之「**奋斗**」、为之牺牲；赞美祖国锦绣山河，用生花妙笔为之「**描画**」、为之歌咏；热爱灿烂语言历史文化，为之「**沉醉**」、为之感动。",
  "ciyu-15": "答案 A。（1）导游大赛入围选手在市民见证下庄严宣誓，用「**宣誓**」；（2）四川方言丰富多彩，言谈间趣味横生，用「**妙趣横生**」；（3）对先进书香家庭授予荣誉称号给予肯定，用「**表彰**」；（4）粉丝常在成名时锦上添花，唯有知音能在落魄寂寞时「**雪中送炭**」。",
  "ciyu-16": "答案 A。第一空在月下仰望，望与「**星空**」搭配；第二空俯视与「**大地**」搭配；第三空听天籁之音，与「**万物**」相融；第四空在雨中感受清新，观细雨与「**垂柳**」相映成趣。全句动宾搭配整饬和谐。",
  "ciyu-17": "答案 B。云彩魔术师的变化过程：时而云蒸霞蔚，玉龙山在云雾中隐现，用「**时隐时现**」；时而碧空澄澈，群峰在日光下展现「**晶莹耀眼**」的雪光；时而云带束腰，轻盈如「**闪峦翠碧**」；时而晚霞似火，展现「**娇艳妩媚**」的万千姿态。",
  "ciyu-18": "答案 C。第一空形容感人故事非常多，用「**不胜枚举**」；第二空人们因各自不同的人生经历走上公益之路，用「**缘由**」；第三空将志愿者精神像种子一样播撒到四方，用「**播撒**」；第四空做志愿者不仅是时尚追求，更是品格情操的「**高尚**」。",
  "ciyu-19": "答案 A。第一句指出花开是常见自然规律，用「**司空见惯**」；第二句转折指出开花时有香气则是额外馈赠，用「**但是**」；第三句说明在独处时这种香气让人顿觉不同寻常，用「**寻常**」；第四句被花香所感染陶醉，用「**沉醉**」。",
  "ciyu-20": "答案 C。松树在雪地中如挺立坚守阵地的卫士，第一空用「**坚守阵地**」；在夕阳残照中如迎风破浪勇敢前行的渔夫，第二空用「**搏击风浪**」；在群山隐匿中如不求名利超脱尘俗的隐士，第三空用「**远离世俗**」。",
  "ciyu-21": "答案 C。（1）对美好未来的向往期待，用「**憧憬**」；（2）草香与艾叶香气交融在一起，用「**混合**」；（3）自然资源禀赋得天之优越，用「**得天独厚**」；（4）电视剧故事情节扣人心弦深深吸引观众，用「**扣人心弦**」。",
  "ciyu-22": "答案 A。（1）工匠对技能精益求精达到极致，用「**追求**」；（2）以客观历史眼光而非道德偏见评断历史人物，用「**评判**」；（3）鸟鸣声悦耳动听，用「**清脆**」；（4）书法艺术将其神韵完美呈现，用「**淋漓尽致**」。",
  "ciyu-23": "答案 A。四句根据人才工作的递进逻辑配置成语：寻找人才像口渴急切求水——「**求贤若渴**」；发现人才如同获得无价之宝——「**如获至宝**」；举荐选拔人才不拘守常规条框——「**不拘一格**」；使用人才让每个人充分施展才能——「**各尽其能**」。",
  "ciyu-24": "答案 A。第一空书籍是汉字构成的精粹结晶，用「**精华**」；第二空好书如山泉令人神清气爽，美景令人「**美不胜收**」；第三空好书像春雨般安抚心灵，用「**抚慰**」；第四空丰富充实精神世界，用「**滋润**」。",
  "ciyu-25": "答案 D。黄河奇石的审美特点：形态各异用「**千姿百态**」，神形兼备逼真如生用「**栩栩如生**」，非人工雕琢、天造地设的最高妙境是「**浑然天成**」。由表及里、由形入神的层递最恰当。",
  "ciyu-26": "答案 C。第一空形容岭南雕刻技艺高超精妙如鬼斧神工，用「**巧夺天工**」；第二空雕刻风格有的粗犷简练，有的「**精雕细刻**」，形成对偶；第三空人物形象生动逼真，用「**惟妙惟肖**」。",
  "ciyu-27": "答案 C。第一、二空语意转折：“物质财富对幸福来说「**并非**」不重要，「**但是**」相比精神快乐而言更具基础性”；第三空引出先秦诸子的主张推论，用「**因此**」；第四空强调内在知足，用「**更加**」；末空引出结论用「**才**」。",
  "ciyu-28": "答案 B。上联指出粉丝往往看重作者的名气与光环（「**成名**」），而真正的知音能读懂作者内心的孤独（「**寂寞**」）；下联递进评价知音不仅能在平淡处识得英才（「**鉴赏/识拔**」），更能开诚布公敢讲真话（「**直言**」）。",
  "ciyu-29": "答案 A。第一空形容知识浩瀚辽阔，用「**广袤**」；第二空科技创新为高质量发展注入动力，用「**赋能**」；第三空传统文化精髓深植于民族精神之中，用「**浸润**」；第四空砥砺奋斗的精神「**赓续**」传承。",
  "ciyu-30": "答案 B。第一空科学探究需要敏锐发现问题的眼光，用「**敏锐**」；第二空探索未知世界需要敢为人先的魄力，用「**胆识**」；第三空将理论成果转化为现实生产力，用「**转化**」；第四空推动经济社会稳健发展，用「**驱动**」。",
  "ciyu-31": "答案 B。第一空语言文字是文化的载体，用「**承载**」；第二空经典名著经受时光淘洗历久弥新，用「**淬炼**」；第三空文学的力量滋养着民族的精神家园，用「**涵养**」；第四空在阅读中品味高雅情趣，用「**涵泳**」。",
  "ciyu-32": "答案 D。第一空江南小镇的宁静清幽，用「**恬静**」；第二空青石板路在细雨中泛着清冷光泽，用「**幽深**」；第三空古老水乡承载悠远的历史记忆，用「**积淀**」；第四空唤起游子心中的缕缕乡愁，用「**羁绊/牵绊**」。",
  "ciyu-33": "答案 D。第一空面对复杂多变的国际形势保持清醒头脑，用「**审视**」；第二空在风浪中坚定信念毫不动摇，用「**坚守**」；第三空凝聚起无坚不摧的磅礴力量，用「**汇聚**」；第四空开创时代崭新局面，用「**开拓**」。",
  "ciyu-34": "答案 A。第一空生态环境保护功在当代利在千秋，用「**关乎**」；第二空让绿水青山成为人民群众的幸福之源，用「**造福**」；第三空生态文明理念深入人心，用「**扎根**」；第四空绘制美丽中国宏伟蓝图，用「**绘就**」。",
  "ciyu-35": "答案 B。第一空对中华优秀传统文化进行创造性转化与创新性发展，用「**转化**」；第二空使古老文物在新时代焕发出新的生机，用「**焕发**」；第三空提升全民族的文化自信心与自豪感，用「**增强**」；第四空展现大国深厚的文化底蕴，用「**彰显**」。",
  "ciyu-36": "答案 B。第一空阅读能开阔我们的视野，用「**拓展**」；第二空思考能深化我们对人生的认知，用「**升华**」；第三空实践能检验真理并锤炼品格，用「**砥砺**」；第四空奋斗能书写精彩人生华章，用「**谱写**」。",
  "ciyu-37": "答案 B。第一空博物馆是连接过去与未来的桥梁，用「**连接**」；第二空陈列的文物无声诉说着灿烂的历史传奇，用「**倾诉**」；第三空让观众近距离感受文明的脉搏，用「**触摸**」；第四空筑牢全民族共同的历史记忆，用「**构筑**」。",
  "ciyu-38": "答案 B。第一空大自然的鬼斧神工令人惊叹，用「**震撼**」；第二空高山峡谷展现出磅礴的气势，用「**雄浑**」；第三空清澈溪流自林间蜿蜒流淌，用「**潺潺**」；第四空人与自然和谐共生的美好图景，用「**勾勒**」。",
  "ciyu-39": "答案 C。全段关联词逻辑链条：“「**不仅**」要在课堂上学好书本理论知识，而且要在课外积极投身社会实践；「**只有**」将学与思紧密结合起来，「**才能**」真正掌握事物的本质；「**如果**」脱离实践闭门造车，终将一事无成。”",
  "ciyu-40": "答案 A。第一空青年一代勇立时代潮头，用「**担当**」时代重任；第二空在改革攻坚战中迎难而上，用「**破局**」；第三空以扎实的专业功底奠定事业基石，用「**奠定**」；第四空在奋斗中实现人生远大抱负，用「**成就**」。",
  "ciyu-41": "答案 B。第一空传统手工艺人对技艺的世代相传，用「**薪火相传**」；第二空数十年如一日耐得住寂寞精雕细琢，用「**守正**」；第三空在传统中融入现代审美设计，用「**出新**」；第四空让非遗技艺重新融入现代生活，用「**回归**」。",
  "ciyu-42": "答案 D。第一空教育是润物无声的心灵工程，用「**润泽**」；第二空引导青少年树立正确的人生价值观，用「**塑造**」；第三空激发孩子们探索求知的潜能，用「**唤醒**」；第四空为国家的未来培育栋梁之材，用「**奠基**」。",
  "ciyu-43": "答案 C。第一空在喧嚣浮躁的尘世中寻求心灵的平静，用「**宁静**」；第二空面对困难挫折展现坚强不屈的品格，用「**从容**」；第三空对待名利得失保持豁达通透的心境，用「**淡泊**」；第四空以宽厚仁爱之心对待周遭人事，用「**包容**」。",
  "ciyu-44": "答案 C。第一空科技创新催生发展新动能，用「**激发**」；第二空数字化赋能千行百业转型升级，用「**驱动**」；第三空破除体制机制障碍，用「**打破**」；第四空全面构建现代化产业体系，用「**构建**」。",
  "ciyu-45": "答案 B。第一空书卷气是一个人最持久的迷人气质，用「**浸润**」；第二空书籍洗去内心的浮躁与狭隘，用「**涤荡**」；第三空拓宽看世界的眼界与胸襟，用「**开阔**」；第四空铸就丰盈笃定的精神世界，用「**丰盈**」。",
  "ciyu-46": "答案 C。第一空中华文明历经数千年风雨沧桑，用「**绵延**」不绝；第二空中华文化在交流互鉴中吸收各方营养，用「**兼收并蓄**」；第三空在守正创新中不断注入生机活力，用「**赓续**」；第四空在世界文明之林独树一帜，用「**屹立**」。",
  "ciyu-47": "答案 D。第一空英雄模范用热血书写忠诚，用「**铸就**」；第二空崇高精神在全社会引起强烈共鸣，用「**激荡**」；第三空让英雄精神成为时代的鲜明坐标，用「**指引**」；第四空激励后人砥砺前行矢志奉献，用「**传承**」。",
  "ciyu-48": "答案 C。第一空城市更新保留城市的历史风貌，用「**留存**」记忆；第二空改善人民群众的生活环境品质，用「**提升**」；第三空让历史文化与现代生活相得益彰，用「**融合**」；第四空打造宜居宜业的现代化都市，用「**塑就**」。",
  "ciyu-49": "答案 C。第一空青春因奋斗而绽放耀眼的光芒，用「**绽放**」；第二空在风浪洗礼中磨砺顽强意志，用「**淬炼**」；第三空扛起国家和时代赋予的使命，用「**肩负**」；第四空书写无愧于先辈的崭新篇章，用「**谱就**」。",
  "ciyu-50": "答案 D。第一空对大自然的馈赠心怀感恩，用「**敬畏**」；第二空统筹山水林田湖草沙一体化保护，用「**协同**」；第三空留住白云碧水绿水青山，用「**守护**」；第四空绘就人与自然和谐共生的壮丽图景，用「**擘画**」。",
  "ciyu-51": "答案 A。第一空家庭家教家风建设是社会和谐的基石，用「**奠定**」；第二空优秀的家风如春雨滋养后代的心田，用「**滋润**」；第三空引导孩子扣好人生的第一粒扣子，用「**树立**」；第四空推动社会主义核心价值观在家庭扎根，用「**生根**」。",
  "ciyu-52": "答案 B。第一空面对时代大考交出优秀答卷，用「**交卷**」；第二空在危机中育先机、于变局中开新局，用「**开拓**」；第三空增强应对风险挑战的韧性与底气，用「**筑牢**」；第四空推动经济高质量发展行稳致远，用「**护航**」。",
  "ciyu-53": "答案 C。第一空诗词歌赋是中华民族的共同精神财富，用「**瑰宝**」；第二空经典名篇代代吟诵历久弥新，用「**传唱**」；第三空唤醒每一个中国人心灵深处的文化基因，用「**唤醒**」；第四空汇聚起实现民族伟大复兴的精神力量，用「**凝聚**」。",
  "ciyu-54": "答案 D。第一空探求真理的道路需要不畏艰险的勇气，用「**跋涉**」；第二空勇于突破传统观念的束缚藩篱，用「**冲破**」；第三空在一次次实验中探寻事物的内在奥秘，用「**探寻**」；第四空最终登上科学攀登的高峰之巅，用「**攀登**」。"
}
